"""Text of the ES Note written to a finding. English and Japanese."""
LABELS = {
    "en": {"title": "Second Opinion Triage suggestion", "disp": "Suggested disposition", "urg": "Suggested urgency",
           "conf": "confidence", "policy": "Policy notes", "expl": "Explanation", "add": "LLM explanation (added)", "foot":
           "Suggestion only. Set the final disposition and urgency in ES. Generated by Second Opinion Triage (decision model %s, questions %s)."},
    "ja": {"title": "セカンドオピニオン トリアージ提案", "disp": "Disposition（提案）", "urg": "Urgency（提案）",
           "conf": "確信度", "policy": "判定ルールの注記", "expl": "説明", "add": "LLM の説明（追記）", "foot":
           "提案のみです。最終的な Disposition と Urgency は ES で設定してください。Second Opinion Triage により作成（判定モデル %s、質問 %s）。"},
}
DISP = {"en": {"TP": "True Positive", "FP": "False Positive", "Benign": "Benign", "Undetermined": "Undetermined"},
        "ja": {"TP": "TP（真陽性）", "FP": "FP（誤検知）", "Benign": "Benign（正常な想定内の動作）", "Undetermined": "判別不可"}}


def build(rec, lang="en"):
    L = LABELS.get(lang, LABELS["en"])
    d = DISP.get(lang, DISP["en"]).get(rec.get("jev_disposition"), rec.get("jev_disposition"))
    lines = ["%s: %s (%s %s)" % (L["disp"], d, L["conf"], rec.get("jev_disposition_confidence")),
             "%s: %s (%s %s)" % (L["urg"], (rec.get("jev_urgency") or "").capitalize(), L["conf"], rec.get("jev_urgency_confidence"))]
    if rec.get("jev_policy"):
        lines.append("%s: %s" % (L["policy"], rec["jev_policy"]))
    if rec.get("jev_explanation") and rec.get("jev_explain_for") == rec.get("jev_time"):
        lines += ["", "%s:" % L["expl"], rec["jev_explanation"]]
    lines += ["", L["foot"] % (rec.get("jev_model"), rec.get("jev_questions"))]
    return L["title"], "\n".join(lines)


def has_explanation(rec):
    """An explanation for the current triage result exists."""
    return bool(rec.get("jev_explanation")) and rec.get("jev_explain_for") == rec.get("jev_time")


def explanation_in_note(rec):
    """The Note already written for this result contains the current explanation.
    jev_note_expl_for = jev_explain_time of the explanation put in the Note (0.9.8+). Older records have
    no such field: the Note had the explanation if the explanation is older than the Note."""
    if not has_explanation(rec):
        return True
    if rec.get("jev_note_expl_for") not in (None, ""):
        return str(rec.get("jev_note_expl_for")) == str(rec.get("jev_explain_time"))
    try:
        return float(rec.get("jev_explain_time") or 0) <= float(rec.get("jev_note_time") or 0)
    except ValueError:
        return False


def build_explanation(rec, lang="en"):
    """A Note with only the LLM explanation, added after the suggestion Note was written."""
    L = LABELS.get(lang, LABELS["en"])
    d = DISP.get(lang, DISP["en"]).get(rec.get("jev_disposition"), rec.get("jev_disposition"))
    lines = ["%s: %s / %s: %s" % (L["disp"], d, L["urg"], (rec.get("jev_urgency") or "").capitalize()),
             "", rec.get("jev_explanation") or "",
             "", L["foot"] % (rec.get("jev_model"), rec.get("jev_questions"))]
    return "%s — %s" % (L["title"], L["add"]), "\n".join(lines)
